S^{i}_{Q, x}\!=\!\frac{exp(-{\alpha}\langle F_{Q,x}, \dot{p}^i\rangle)}{\sum_{\dot{p}^i\in\dot{\mathbbm{P}}}exp(-{\alpha}\langle F_{Q,x}, \dot{p}^i\rangle)},
\end{equation}
where $\langle a, b\rangle$ represents the computation of cosine similarity between $a$ and $b$, $\alpha$ is an amplification factor. 
The predicted segmentation mask is then given by 
\begin{equation}
    \hat{M}_{Q, x}=\mathop{\arg\max}_{i}S^{i}_{Q, x}.
\label{eq:predictedmask}
\end{equation}
Learning proceeds by minimizing the negative log-probability 
\begin{equation}
    \mathcal{L}_{seg}=-\frac{1}{N}\sum_{x}\sum_{i}\mathbbm{1}({M}_{Q,x}=i)logS^{i}_{Q, x},
\label{eq:loss_seg}
\end{equation}
where $N$ is the total number of points, and ${M}_{Q}$ is the ground truth mask of query point cloud ${I}_{Q}$.

